DROP TABLE IF EXISTS country_currencies;
DROP TABLE IF EXISTS countries;

CREATE TABLE countries (
    alpha_2              TEXT,
    alpha_3              TEXT,
    numeric_code         TEXT,
    name                 TEXT,
    status               TEXT,
    independent          INTEGER      NOT NULL,
    official_name        TEXT,
    region               TEXT,
    subregion            TEXT,
    intermediate_region  TEXT,
    calling_codes        TEXT,
    tlds                 TEXT,
    languages            TEXT,
    borders              TEXT,
    note                 TEXT,
    last_verified        TEXT,
    withdrawal_date      TEXT,
    replaced_by          TEXT,
    PRIMARY KEY (alpha_2, status)
);

CREATE TABLE country_currencies (
    country_alpha_2 TEXT NOT NULL,
    currency_code   TEXT NOT NULL,
    PRIMARY KEY (country_alpha_2, currency_code)
);

